import os from "node:os";
import path from "node:path";
/**
 * Portable user-local MSSR state root shared by host adapters and background
 * infrastructure such as semantic-curation queues. Project authority remains
 * inside each project's .mssr directory; this root is operational state only.
 */
export function defaultMssrStateRoot(platform = process.platform, home = os.homedir(), localAppData = process.env.LOCALAPPDATA, xdgStateHome = process.env.XDG_STATE_HOME, configuredRoot = process.env.MSSR_STATE_ROOT) {
    if (configuredRoot?.trim())
        return path.resolve(configuredRoot.trim());
    if (platform === "win32" && localAppData)
        return path.join(localAppData, "MauroPrime", "MSSR");
    if (platform === "darwin")
        return path.join(home, "Library", "Application Support", "MauroPrime", "MSSR");
    if (platform !== "win32" && xdgStateHome)
        return path.join(xdgStateHome, "mssr");
    return path.join(home, ".local", "state", "mssr");
}
